  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md classifies T-001–T-006 high for execution-proof, trust, protected launch and notification-control changes. T-007/T-008 are medium and explicitly restrict changes to evaluated adoption metadata, validated activation references and release/documentation; capability, authorization and transport algorithms remain outside their scope."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Every high-risk task, T-001–T-006, explicitly requires failing tests committed before implementation, captured Red→Green evidence and a named independent reviewer verdict in Done When. No task declares critical risk."
    },
    {
      "id": "TASK-SIZE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-001 Scope and Planned Files combine four implementation areas: revision/dependency planning in verification-impact.py, bounded workflow interpretation in verification-workflow.py, runner integration in verification.py, and a new execution-evidence aggregate in verification-ci.py. Done When additionally requires revision topology, dependency/step closure, activation identity, rerun provenance, receipt rejection and baseline inventory parity. These exceed a focused single-session implementation unit and combine changes to both evidence producers and their verifier before independent task completion. Split planning/obligation production from execution-evidence aggregation, with an explicit contract dependency and corresponding test ownership."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "acceptance-tests.md includes malformed/missing CI inputs and evidence under AC-001–AC-006, configuration/access/identity failures under AC-012–AC-016, maintenance failures under AC-017, and native-precedence/comment-only failures under AC-018. T-007 additionally requires withholding failed candidates and retaining failed evaluation results; T-008 keeps unproven categories full and records unavailable hosted branches."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001/T-004 plan unit and integration fixtures for module and transport boundaries; T-002/T-005 plan workflow and renderer/installer integration across components; T-006 explicitly uses fixture-driven protocol integration. T-007 acceptance evaluation names AC-013/AC-019 and fixed artifact-based trials. Hosted execution is distinguished from deterministic fixtures in T-008."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001–T-006 each require documented and tested rollback in a disposable checkout with before/after hashes and baseline results. The shared rollback section specifies force-full CI recovery and validated model pin/prior-release recovery while preserving ledgers, frozen history and access/consent checks."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Shared file ordering assigns distinct catalog purposes to planner, workflow, suite registration, maintenance and activation tasks. T-004 transport changes precede T-005 installed-entry integration; T-007 adoption references follow core and installed integration. The explicit one-task-at-a-time rule serializes shared catalog edits without granting overlapping algorithm ownership."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-002 consumes T-001 plans and inventory; T-003 registers model suites against the integrated CI/catalog surface; T-004 consumes T-003 immutable selections; T-005 consumes protected transports; T-006 consumes shared policy; T-007 consumes installed entries; T-008 joins maintenance and adoption for final documentation/release. T-006 and T-007 have no artificial dependency on each other."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "SKIP",
      "severity": "Major",
      "finding": "SKIP: no bugfix or debugging task in scope."
    }
  ],
  "findings": [
    {
      "check_id": "TASK-SIZE",
      "severity": "Major",
      "task_id": "T-001",
      "finding": "specs/ci-model-modernization/tasks.md T-001 Scope, Planned Files and Done When combine revision/dependency planning, bounded workflow interpretation, runner integration and new execution-evidence aggregation into one high-risk task. design.md Components identifies these as separate implementation components. The combined revision, closure, activation, rerun, receipt and inventory obligations exceed a focused single-session unit and defer independent verification until both evidence production and verification have changed. Split planning/obligation production from execution-evidence aggregation, preserving an explicit contract dependency and unique test ownership."
    }
  ]
